(2126438, 291595, 1041, '<td valign="top">Nice contrast of texture and color.  Like the post-processing, too.  Not sure it''s really an abstract since at least the rope is fairly recognizable.</td>', 'Nice contrast of texture and color.  Like the post-processing, too.  Not sure it''s really an abstract since at least the rope is fairly recognizable.', '2006-02-06 09:27:11.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2126444, 291605, 1041, '<td valign="top">Yep, an abstract.  I can tell it''s some sort of a glass object, but not exactly what.  I have to confess the thing that draws most of my attention in the image is the orange area in the bottom left (flame?), and just in general the lower part of the image (more color and texture going on), so overall, it feels a bit unbalanced to me.</td>', 'Yep, an abstract.  I can tell it''s some sort of a glass object, but not exactly what.  I have to confess the thing that draws most of my attention in the image is the orange area in the bottom left (flame?), and just in general the lower part of the image (more color and texture going on), so overall, it feels a bit unbalanced to me.', '2006-02-06 09:29:02.000000', NULL, 1),
(2126473, 289701, 18349, '<td valign="top">This is stunning in it''s simplicity and beauty.  I also like it because my name is in there.  ;)</td>', 'This is stunning in it''s simplicity and beauty.  I also like it because my name is in there.  ;)', '2006-02-06 09:55:33.000000', NULL, 1),
(2126477, 291227, 18349, '<td valign="top">One of my few 10s.  This is beautiful with a great "high art" appeal.  I love the frame as well (but I bet the border patrol is out in force).  Lovely image!  :)</td>', 'One of my few 10s.  This is beautiful with a great "high art" appeal.  I love the frame as well (but I bet the border patrol is out in force).  Lovely image!  :)', '2006-02-06 10:01:20.000000', NULL, 1),
(2126486, 291573, 1041, '<td valign="top">Interesting pic, three very different areas, both for tonality and texture.  I think I would prefer a little more DOF for the top part.</td>', 'Interesting pic, three very different areas, both for tonality and texture.  I think I would prefer a little more DOF for the top part.', '2006-02-06 10:09:11.000000', NULL, 1),
(2126492, 288625, 1041, '<td valign="top">Nice capture, sort of abstract, like the contrast between the stone carving and the blue sky, however, your sky is very pixelated on the right, which I find distracting.  Saving at a higher quality setting (to use the available 150kb) would probably solve this.</td>', 'Nice capture, sort of abstract, like the contrast between the stone carving and the blue sky, however, your sky is very pixelated on the right, which I find distracting.  Saving at a higher quality setting (to use the available 150kb) would probably solve this.', '2006-02-06 10:12:43.000000', NULL, 1),
(2126496, 291223, 1041, '<td valign="top">Very nice colors and textures and shapes.  I have absolutely no clue what I''m looking at ... for once that''s a plus in a DPC challenge :) Only thing I find slightly distracting is the OOF lower left corner.  Wonder if a different crop would''ve improved that, or if you would''ve been able to take the shot with greater DOF.</td>', 'Very nice colors and textures and shapes.  I have absolutely no clue what I''m looking at ... for once that''s a plus in a DPC challenge :) Only thing I find slightly distracting is the OOF lower left corner.  Wonder if a different crop would''ve improved that, or if you would''ve been able to take the shot with greater DOF.', '2006-02-06 10:14:25.000000', NULL, 1),
(2126512, 291164, 40820, '<td valign="top">interesting interpretation!!...like the grain and color tones...pleasing image!</td>', 'interesting interpretation!!...like the grain and color tones...pleasing image!', '2006-02-06 10:25:43.000000', NULL, 1),
(2126517, 291836, 35357, '<td valign="top">Nice snag, looks like old box springs.  Good eye, who woulda thought it would make such an interesting abstract!</td>', 'Nice snag, looks like old box springs.  Good eye, who woulda thought it would make such an interesting abstract!', '2006-02-06 10:28:01.000000', NULL, 1),
(2126518, 291738, 35357, '<td valign="top">Shag carpet?  Pretty gross looking, good eye!</td>', 'Shag carpet?  Pretty gross looking, good eye!', '2006-02-06 10:29:28.000000', NULL, 1),
(2126519, 290076, 40820, '<td valign="top">love the symmetry of this shot....good luck</td>', 'love the symmetry of this shot....good luck', '2006-02-06 10:30:48.000000', NULL, 1),
(2126525, 291191, 46442, '<td valign="top">Looks too much like it was drawn in Photoshop. Just doesn''t look like it was taken with a camera.</td>', 'Looks too much like it was drawn in Photoshop. Just doesn''t look like it was taken with a camera.', '2006-02-06 10:32:58.000000', NULL, 1),
(2126526, 291752, 35357, '<td valign="top">Hehe... "Man Versus Nature"  Making good use of Grandma''s piece of wood.</td>', 'Hehe... "Man Versus Nature"  Making good use of Grandma''s piece of wood.', '2006-02-06 10:33:16.000000', NULL, 1),
(2126529, 290438, 40820, '<td valign="top">great symmetry and depth to this shot!</td>', 'great symmetry and depth to this shot!', '2006-02-06 10:35:02.000000', NULL, 1),
(2126534, 290690, 40376, '<td valign="top">Please tell me how you did this !!<br/>Very abstract but looks more like a painting than a photo ?<br/>Am curious !<br/>7.</td>', 'Please tell me how you did this !!Very abstract but looks more like a painting than a photo ?Am curious !7.', '2006-02-06 10:38:31.000000', NULL, 1),
