INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2128212, 289914, 35786, '<td valign="top">great abstract and colors, just wish it were more crisp</td>', 'great abstract and colors, just wish it were more crisp', '2006-02-06 22:34:35.000000', NULL, 1),
(2128225, 291678, 47852, '<td valign="top">I like the lines, but I think this might benefit from some more dramatic lighting.</td>', 'I like the lines, but I think this might benefit from some more dramatic lighting.', '2006-02-06 22:36:22.000000', NULL, 1),
(2128272, 289644, 35334, '<td valign="top">I love the feeling and texture of this. It seems that something has been locked up and the key thrown away.<br/> <br/>In comparison to the other aspects of the image, the composition seems weak; the lock is a big rectangular shape right in the middle of the frame. I think a different camera angle would have helped; maybe moving the camera up a few inches and looking down on the lock would have given a more dynamic composition.</td>', 'I love the feeling and texture of this. It seems that something has been locked up and the key thrown away. In comparison to the other aspects of the image, the composition seems weak; the lock is a big rectangular shape right in the middle of the frame. I think a different camera angle would have helped; maybe moving the camera up a few inches and looking down on the lock would have given a more dynamic composition.', '2006-02-06 22:44:52.000000', NULL, 1),
(2128322, 291050, 47852, '<td valign="top">Bottom of a shoe?  I like the lighting here and the crop.  Well done!</td>', 'Bottom of a shoe?  I like the lighting here and the crop.  Well done!', '2006-02-06 22:58:48.000000', NULL, 1),
(2128327, 291836, 47852, '<td valign="top">Boxspring from a bed?  I like the mixture of lines and curves here.  Good eye to have seen this one!</td>', 'Boxspring from a bed?  I like the mixture of lines and curves here.  Good eye to have seen this one!', '2006-02-06 22:59:51.000000', NULL, 1),
(2128332, 289018, 47852, '<td valign="top">Qtips?  Great lighting/coloring!</td>', 'Qtips?  Great lighting/coloring!', '2006-02-06 23:00:54.000000', NULL, 1),
(2128336, 291570, 47852, '<td valign="top">I like the colors and the symmetrical nature of this one.</td>', 'I like the colors and the symmetrical nature of this one.', '2006-02-06 23:02:03.000000', NULL, 1),
(2128338, 291812, 47852, '<td valign="top">Is this a roll of that plastic fence stuff?  Maybe a quick bath with a hose to get some of the dirt off, leaving a smoother surface.  I like the shapes and the depth here (even if I''m way off about what it actually is).  Nice job!</td>', 'Is this a roll of that plastic fence stuff?  Maybe a quick bath with a hose to get some of the dirt off, leaving a smoother surface.  I like the shapes and the depth here (even if I''m way off about what it actually is).  Nice job!', '2006-02-06 23:02:19.000000', NULL, 1),
(2128362, 291085, 47852, '<td valign="top">I like the way this one is focused in the center but blurs out without making you dizzy, and the colors are great too.  But those numbers and the little target signs... I don''t see the purpose and find them awkward and distracting.</td>', 'I like the way this one is focused in the center but blurs out without making you dizzy, and the colors are great too.  But those numbers and the little target signs... I don''t see the purpose and find them awkward and distracting.', '2006-02-06 23:05:31.000000', NULL, 1),
