(2129639, 291223, 30982, '<td valign="top">Marvelous title; no idea what it is; pleasing image.</td>', 'Marvelous title; no idea what it is; pleasing image.', '2006-02-07 12:08:23.000000', NULL, 1),
(2129641, 291131, 30982, '<td valign="top">Like the soft, muted colors.  No idea what it is.</td>', 'Like the soft, muted colors.  No idea what it is.', '2006-02-07 12:09:33.000000', NULL, 1),
(2129642, 291255, 30982, '<td valign="top">Like the diagonals; like the different textures, colors in play here.  Lighting is well done, imo.</td>', 'Like the diagonals; like the different textures, colors in play here.  Lighting is well done, imo.', '2006-02-07 12:10:21.000000', NULL, 1),
(2129644, 290513, 24642, '<td valign="top">I like the composition.  The lighting really helps to bring out the texture and colors.  Good work.</td>', 'I like the composition.  The lighting really helps to bring out the texture and colors.  Good work.', '2006-02-07 12:10:33.000000', NULL, 1),
(2129647, 290360, 30982, '<td valign="top">Nice angle to abstract the sign.  Placement in the frame is good.  Bottom looks "cut off" but I suspect that''s a factor of the sign itself.</td>', 'Nice angle to abstract the sign.  Placement in the frame is good.  Bottom looks "cut off" but I suspect that''s a factor of the sign itself.', '2006-02-07 12:12:09.000000', NULL, 1),
(2129650, 291497, 30982, '<td valign="top">The colors, the texture, the clarity of the image all combine for a very nice presentation.</td>', 'The colors, the texture, the clarity of the image all combine for a very nice presentation.', '2006-02-07 12:14:55.000000', NULL, 1),
(2129654, 291688, 30982, '<td valign="top">Heh - this is almost cheating!  Nice angle to get in the eclectic shapes.  Shadow on the lower left, while a bit annoying, does at least echo the angle of the shape above it.</td>', 'Heh - this is almost cheating!  Nice angle to get in the eclectic shapes.  Shadow on the lower left, while a bit annoying, does at least echo the angle of the shape above it.', '2006-02-07 12:15:58.000000', NULL, 1),
(2129661, 291527, 30982, '<td valign="top">Great color, interesting subject.</td>', 'Great color, interesting subject.', '2006-02-07 12:18:33.000000', NULL, 1),
(2129729, 291844, 30982, '<td valign="top">A good idea for the challenge but needs a bit more sharpness, I think.</td>', 'A good idea for the challenge but needs a bit more sharpness, I think.', '2006-02-07 12:51:46.000000', NULL, 1),
(2129731, 291583, 30982, '<td valign="top">Novel approach.</td>', 'Novel approach.', '2006-02-07 12:52:42.000000', NULL, 1),
(2129732, 289823, 50056, '<td valign="top">Very cool...love the blue against black and the lines.  Good luck.</td>', 'Very cool...love the blue against black and the lines.  Good luck.', '2006-02-07 12:52:45.000000', NULL, 1),
(2129734, 291216, 30982, '<td valign="top">Probably not what most would consider "abstract" but lovely capture of the sky in the mirrors.</td>', 'Probably not what most would consider "abstract" but lovely capture of the sky in the mirrors.', '2006-02-07 12:53:26.000000', NULL, 1),
(2129735, 291406, 30982, '<td valign="top">I like the composition of this.  Might have preferred something other than blue for the background - maybe I''m just a bit tired of blue from the other challenge!</td>', 'I like the composition of this.  Might have preferred something other than blue for the background - maybe I''m just a bit tired of blue from the other challenge!', '2006-02-07 12:54:39.000000', NULL, 1),
(2129761, 291505, 24642, '<td valign="top">A good photograph with interesting abstract qualities.  A different title that didn''t relate to the subject would be more fitting for this challenge.</td>', 'A good photograph with interesting abstract qualities.  A different title that didn''t relate to the subject would be more fitting for this challenge.', '2006-02-07 13:13:31.000000', NULL, 1),
(2129766, 291604, 24642, '<td valign="top">Good color rhythm and flow</td>', 'Good color rhythm and flow', '2006-02-07 13:14:54.000000', NULL, 1),
