(2129970, 291505, 30982, '<td valign="top">This is an excellent take on the challenge (imo, of course) but I do think the white part in the upper left is overpowering a bit.  A tighter crop on that side might provide a bit more balance, but may not given the dark lower right third, which works the way it is.</td>', 'This is an excellent take on the challenge (imo, of course) but I do think the white part in the upper left is overpowering a bit.  A tighter crop on that side might provide a bit more balance, but may not given the dark lower right third, which works the way it is.', '2006-02-07 14:45:37.000000', NULL, 1),
(2129974, 291660, 30982, '<td valign="top">Very much an abstract - nicely balanced, looks like an oil painting.</td>', 'Very much an abstract - nicely balanced, looks like an oil painting.', '2006-02-07 14:47:17.000000', NULL, 1),
(2129976, 291233, 30982, '<td valign="top">This one is very elegant, very simple.</td>', 'This one is very elegant, very simple.', '2006-02-07 14:48:56.000000', NULL, 1),
