(2129991, 291537, 34134, '<td valign="top">This is one of my all time favorites!!</td>', 'This is one of my all time favorites!!', '2006-02-07 14:53:50.000000', NULL, 1),
(2129993, 290853, 30982, '<td valign="top">I really like this except for the OOF part in the front right.  I do realize you were probably aiming for this - it''s just my personal taste that I''d like that OOF section to be smaller.  I''d want the viewer''s eye to be drawn more to the crispness of the rest of the picture.  Maybe if a little less OOF.  Rambling... anyway, I really do like this.</td>', 'I really like this except for the OOF part in the front right.  I do realize you were probably aiming for this - it''s just my personal taste that I''d like that OOF section to be smaller.  I''d want the viewer''s eye to be drawn more to the crispness of the rest of the picture.  Maybe if a little less OOF.  Rambling... anyway, I really do like this.', '2006-02-07 14:56:50.000000', NULL, 1),
(2130003, 291541, 30982, '<td valign="top">I do like the "mixed media" here - makes for a very interesting picture.  Might even like it upside down just as much.</td>', 'I do like the "mixed media" here - makes for a very interesting picture.  Might even like it upside down just as much.', '2006-02-07 14:58:38.000000', NULL, 1),
(2130007, 291340, 30982, '<td valign="top">Very cool!</td>', 'Very cool!', '2006-02-07 14:59:38.000000', NULL, 1),
(2130014, 291596, 30982, '<td valign="top">I find this very appealing, with the difference in textures, the use rather than avoidance of shadows.  Only constructive comment - the black used in the lower right corner either needs less texture or more.</td>', 'I find this very appealing, with the difference in textures, the use rather than avoidance of shadows.  Only constructive comment - the black used in the lower right corner either needs less texture or more.', '2006-02-07 15:02:17.000000', NULL, 1),
