(2132972, 290935, 35602, '<td valign="top">Great colors.  Very good macro, also.  It appears to me that these were beads strung on beading string, and the detail of the string is really sharp.  Great job.</td>', 'Great colors.  Very good macro, also.  It appears to me that these were beads strung on beading string, and the detail of the string is really sharp.  Great job.', '2006-02-08 07:39:56.000000', NULL, 1),
(2132980, 289742, 35602, '<td valign="top">The glare spots hurt this photo.  Try using a neutral density filter to equalize the highlights and shadows.</td>', 'The glare spots hurt this photo.  Try using a neutral density filter to equalize the highlights and shadows.', '2006-02-08 07:41:14.000000', NULL, 1),
