(2134458, 289818, 22734, '<td valign="top">Very interesting giving the impression of mixed media.</td>', 'Very interesting giving the impression of mixed media.', '2006-02-08 15:16:31.000000', NULL, 1),
(2134468, 291604, 22734, '<td valign="top">Yes, this is abstract but the image fails to deliver its full potential as all remains too clouded and the intention ambiguous. Its strong point are the diagonals sweeping across. Yet this alone gives the image merit. 6</td>', 'Yes, this is abstract but the image fails to deliver its full potential as all remains too clouded and the intention ambiguous. Its strong point are the diagonals sweeping across. Yet this alone gives the image merit. 6', '2006-02-08 15:20:34.000000', NULL, 1),
