(2135791, 291542, 10867, '<td valign="top">This is a really beautiful image.  Since its subject is very easily recognizable, however, I''m not sure it really can be seen as an abstract.</td>', 'This is a really beautiful image.  Since its subject is very easily recognizable, however, I''m not sure it really can be seen as an abstract.', '2006-02-09 00:10:10.000000', NULL, 1),
(2135795, 291752, 10867, '<td valign="top">Very interesting image!</td>', 'Very interesting image!', '2006-02-09 00:12:21.000000', NULL, 1),
(2135800, 289910, 10867, '<td valign="top">This is an interesting reflection shot, but since its subject matter is very easily recognizable and not really "abstracted", I don''t think that it''s really appropriate for this challenge.</td>', 'This is an interesting reflection shot, but since its subject matter is very easily recognizable and not really "abstracted", I don''t think that it''s really appropriate for this challenge.', '2006-02-09 00:17:29.000000', NULL, 1),
(2135801, 291418, 10867, '<td valign="top">Wonderful colours, texturees and design.  Great lighting, too.  A 9 from me!</td>', 'Wonderful colours, texturees and design.  Great lighting, too.  A 9 from me!', '2006-02-09 00:20:34.000000', NULL, 1),
