(2135814, 290764, 10867, '<td valign="top">Ah, a Yeats fan!  This is a very interesting image.  I think, though, that it would be even more effective if the "eye" of the gyre were a bit closer to being tack sharp.</td>', 'Ah, a Yeats fan!  This is a very interesting image.  I think, though, that it would be even more effective if the "eye" of the gyre were a bit closer to being tack sharp.', '2006-02-09 00:32:07.000000', NULL, 1),
(2135824, 291571, 25754, '<td valign="top">you did a great job capturing the blurred motion. as this is an abstract i think it might have been better to exclude the recognizable foot in focus to the far left.</td>', 'you did a great job capturing the blurred motion. as this is an abstract i think it might have been better to exclude the recognizable foot in focus to the far left.', '2006-02-09 00:39:32.000000', NULL, 1),
(2135832, 290762, 25754, '<td valign="top">excellent abstract. I very much like the sci-fi feel of this.</td>', 'excellent abstract. I very much like the sci-fi feel of this.', '2006-02-09 00:41:28.000000', NULL, 1),
(2136064, 291534, 48545, '<td valign="top">simple and elegant, I really enjoyed this photo, I''m presuming it is a couple of vases...</td>', 'simple and elegant, I really enjoyed this photo, I''m presuming it is a couple of vases...', '2006-02-09 03:40:58.000000', NULL, 1),
(2136065, 291230, 48545, '<td valign="top">colour balance is great, a really interesting photo to look at.  It almost feels like a painted image apart from of the light stokes, this makes it even more compelling.</td>', 'colour balance is great, a really interesting photo to look at.  It almost feels like a painted image apart from of the light stokes, this makes it even more compelling.', '2006-02-09 03:42:50.000000', NULL, 1),
