(2136200, 290596, 31885, '<td valign="top">Nice colours, nice lines, nice texture, but I''m not sure it''s really abstract.</td>', 'Nice colours, nice lines, nice texture, but I''m not sure it''s really abstract.', '2006-02-09 06:51:40.000000', NULL, 1),
(2136203, 291660, 31885, '<td valign="top">Very interesting. Beautiful lines and colours, I''d love to know how you did this. I''m guessing some motion panning is involved?</td>', 'Very interesting. Beautiful lines and colours, I''d love to know how you did this. I''m guessing some motion panning is involved?', '2006-02-09 06:54:57.000000', NULL, 1),
