(2136219, 291712, 31885, '<td valign="top">I like soft feel and the strong colours. Good simple composition too, should do well.</td>', 'I like soft feel and the strong colours. Good simple composition too, should do well.', '2006-02-09 07:14:11.000000', NULL, 1),
(2136222, 291223, 31885, '<td valign="top">You got the title just right LOL! Beautiful striking image.</td>', 'You got the title just right LOL! Beautiful striking image.', '2006-02-09 07:15:53.000000', NULL, 1),
