(2136242, 291006, 53032, '<td valign="top">colors are rather distracting, do not feel soothing.  Looks like it could be a selection out of a photoshop color pallet instead of a photo.</td>', 'colors are rather distracting, do not feel soothing.  Looks like it could be a selection out of a photoshop color pallet instead of a photo.', '2006-02-09 07:23:55.000000', NULL, 1),
(2136244, 291701, 53032, '<td valign="top">photo seems to busy, does not draw the eye.</td>', 'photo seems to busy, does not draw the eye.', '2006-02-09 07:24:32.000000', NULL, 1),
(2136250, 291834, 53032, '<td valign="top">I would not consider snow on a few twis an abstract.  The framing of the image could be better.  Good DOF control and exposure control overal.</td>', 'I would not consider snow on a few twis an abstract.  The framing of the image could be better.  Good DOF control and exposure control overal.', '2006-02-09 07:27:21.000000', NULL, 1),
