(2136429, 291227, 48228, '<td valign="top">Sharp, bold, dramatic, and great contrasting colors, with the black and red.....</td>', 'Sharp, bold, dramatic, and great contrasting colors, with the black and red.....', '2006-02-09 08:53:40.000000', NULL, 1),
