(2136835, 291491, 30982, '<td valign="top">Drops are getting a bit overdone here at DPC (in my opinion) and this one is a bit bland as drops go.</td>', 'Drops are getting a bit overdone here at DPC (in my opinion) and this one is a bit bland as drops go.', '2006-02-09 12:35:23.000000', NULL, 1),
(2136837, 290371, 30982, '<td valign="top">Kind of looks like the inside of a car wash place.  Overall, though it''s lacking in any feel of "depth" and the bright spots don''t add to the picture, in my opinion.</td>', 'Kind of looks like the inside of a car wash place.  Overall, though it''s lacking in any feel of "depth" and the bright spots don''t add to the picture, in my opinion.', '2006-02-09 12:36:24.000000', NULL, 1),
