(2136841, 291584, 30982, '<td valign="top">Image seems a bit "dirty" in color and clarity.</td>', 'Image seems a bit "dirty" in color and clarity.', '2006-02-09 12:38:10.000000', NULL, 1),
(2136845, 291436, 30982, '<td valign="top">Abstract?  Not exactly to me - seems more like an out of focus snapshot.</td>', 'Abstract?  Not exactly to me - seems more like an out of focus snapshot.', '2006-02-09 12:38:59.000000', NULL, 1),
