(2137522, 288135, 40679, '<td valign="top">nice framing and beautiful colors! I like the way my eyes go up and down :)</td>', 'nice framing and beautiful colors! I like the way my eyes go up and down :)', '2006-02-09 16:43:24.000000', NULL, 1),
(2137524, 291131, 40679, '<td valign="top">I think the colors would burst more if they weren''t pastel. Normally I like shots like these, but I think it needs a bit of a spark.</td>', 'I think the colors would burst more if they weren''t pastel. Normally I like shots like these, but I think it needs a bit of a spark.', '2006-02-09 16:44:26.000000', NULL, 1),
(2137526, 291847, 40679, '<td valign="top">are these coins? Like the greys &amp; DoF!</td>', 'are these coins? Like the greys & DoF!', '2006-02-09 16:45:07.000000', NULL, 1),
(2137532, 290693, 40679, '<td valign="top">It is abstract, can''t seem to find out what this is ;)<br/> <br/>I like the colors, but the lighting is a bit harsh for me.</td>', 'It is abstract, can''t seem to find out what this is ;) I like the colors, but the lighting is a bit harsh for me.', '2006-02-09 16:46:39.000000', NULL, 1),
(2137533, 288256, 40679, '<td valign="top">looks like digital art, but I like it. wonder how you did this. great colors!</td>', 'looks like digital art, but I like it. wonder how you did this. great colors!', '2006-02-09 16:47:40.000000', NULL, 1),
(2137536, 291440, 40679, '<td valign="top">I think your photo is a bit flat, could use a bit DoF by changing your viewpoint</td>', 'I think your photo is a bit flat, could use a bit DoF by changing your viewpoint', '2006-02-09 16:48:24.000000', NULL, 1),
(2137540, 290853, 40679, '<td valign="top">nice detail! the DoF is a bit small IMO, especially the right part of your photo could use a bit more focus.</td>', 'nice detail! the DoF is a bit small IMO, especially the right part of your photo could use a bit more focus.', '2006-02-09 16:49:17.000000', NULL, 1),
(2137548, 290780, 40679, '<td valign="top">they''re beautiful :) my eyes are fooling me, it looks like the photo is skewed :)</td>', 'they''re beautiful :) my eyes are fooling me, it looks like the photo is skewed :)', '2006-02-09 16:50:15.000000', NULL, 1),
(2137550, 289018, 40679, '<td valign="top">the soft colors really work with these soft objects :) I like the random order of the Q''s :)</td>', 'the soft colors really work with these soft objects :) I like the random order of the Q''s :)', '2006-02-09 16:51:10.000000', NULL, 1),
(2137551, 291688, 40679, '<td valign="top">your photo seems a bit messy; there isn''t one main-object &amp; there are some things on it I would crop (left &amp; right top)</td>', 'your photo seems a bit messy; there isn''t one main-object & there are some things on it I would crop (left & right top)', '2006-02-09 16:52:27.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2137557, 291182, 40679, '<td valign="top">great colors &amp; I think the movement is cool, but I miss some focus here.</td>', 'great colors & I think the movement is cool, but I miss some focus here.', '2006-02-09 16:54:16.000000', NULL, 1),
(2137568, 291659, 40679, '<td valign="top">I always thought abstract was about sharp lines &amp; colors, but with your photo you''re prooving the opposite is possible too :) great job!</td>', 'I always thought abstract was about sharp lines & colors, but with your photo you''re prooving the opposite is possible too :) great job!', '2006-02-09 16:55:28.000000', NULL, 1),
(2137572, 291230, 40679, '<td valign="top">this is art. could have been painted. love it!</td>', 'this is art. could have been painted. love it!', '2006-02-09 16:56:19.000000', NULL, 1),
(2137580, 291418, 40679, '<td valign="top">I think your photo needs some contrast and is a bit grainy, but I love the compo :)</td>', 'I think your photo needs some contrast and is a bit grainy, but I love the compo :)', '2006-02-09 16:57:10.000000', NULL, 1),
(2137590, 291835, 40679, '<td valign="top">nice lighting &amp; compo. could use a bit more DoF</td>', 'nice lighting & compo. could use a bit more DoF', '2006-02-09 17:00:08.000000', NULL, 1),
(2137629, 291830, 7743, '<td valign="top">Woody in the abstract.  hehe</td>', 'Woody in the abstract.  hehe', '2006-02-09 17:12:22.000000', NULL, 1),
(2137635, 289931, 43565, '<td valign="top">Modern art sculpture?</td>', 'Modern art sculpture?', '2006-02-09 17:14:44.000000', NULL, 1),
(2137652, 291697, 43565, '<td valign="top">This is not an abstract according to the challenge details.</td>', 'This is not an abstract according to the challenge details.', '2006-02-09 17:20:02.000000', NULL, 1),
(2137678, 291216, 2158, '<td valign="top">This is a great shot, but it doesn''t really fit the challenge <i>as described.</i></td>', 'This is a great shot, but it doesn''t really fit the challenge as described.', '2006-02-09 17:29:52.000000', NULL, 1),
(2137682, 291820, 43565, '<td valign="top">I like the upper left corner and the colors, but I wish more was in focus.</td>', 'I like the upper left corner and the colors, but I wish more was in focus.', '2006-02-09 17:31:25.000000', NULL, 1),
(2137734, 289478, 1041, '<td valign="top">This is borderline abstract to me.  A little too recognizable.  Having said that, I like the colors, the contrast of the soft feathers against the hard metal and how the chain is looped to lead the eye through the photo.</td>', 'This is borderline abstract to me.  A little too recognizable.  Having said that, I like the colors, the contrast of the soft feathers against the hard metal and how the chain is looped to lead the eye through the photo.', '2006-02-09 17:48:43.000000', NULL, 1),
(2137771, 291061, 16488, '<td valign="top">nice (but avoid putting explanations in your title)</td>', 'nice (but avoid putting explanations in your title)', '2006-02-09 18:00:13.000000', NULL, 1),
(2137793, 288625, 42984, '<td valign="top">Lovely clarity and depth of colour. The blue looks deep enough to be water, are you using an polarizing filter?</td>', 'Lovely clarity and depth of colour. The blue looks deep enough to be water, are you using an polarizing filter?', '2006-02-09 18:09:42.000000', NULL, 1),
(2137794, 291372, 42984, '<td valign="top">Incredible shell, great capture. Would have scored well in white on white too</td>', 'Incredible shell, great capture. Would have scored well in white on white too', '2006-02-09 18:10:30.000000', NULL, 1),
(2137796, 291661, 42984, '<td valign="top">Probably not abstract enough in that its easy to see all of the elements as they really are</td>', 'Probably not abstract enough in that its easy to see all of the elements as they really are', '2006-02-09 18:11:09.000000', NULL, 1),
(2137799, 291578, 42984, '<td valign="top">Fascinating and impossible to determine what it is. My guess is that the title is just to put us off too.</td>', 'Fascinating and impossible to determine what it is. My guess is that the title is just to put us off too.', '2006-02-09 18:12:00.000000', NULL, 1),
(2137804, 291803, 42984, '<td valign="top">Interesting, kind of gave it away with the title. I wonder why you didn''t rotate to get the verticals correct. It sort of looks sloppy and therefore not planned or cared about</td>', 'Interesting, kind of gave it away with the title. I wonder why you didn''t rotate to get the verticals correct. It sort of looks sloppy and therefore not planned or cared about', '2006-02-09 18:13:08.000000', NULL, 1),
(2137806, 291712, 42984, '<td valign="top">Very very good. Great light on the blue and a really well balance composition. Could appear in a corporate reception area aas a quality piece of art</td>', 'Very very good. Great light on the blue and a really well balance composition. Could appear in a corporate reception area aas a quality piece of art', '2006-02-09 18:14:04.000000', NULL, 1),
(2137824, 291436, 42984, '<td valign="top">Just too much out of focus. It really only needs one little thing to be sharp for the effect you''re trying to get. That would disguise what the actual patterns really are but also show people that the OOF was deliberate</td>', 'Just too much out of focus. It really only needs one little thing to be sharp for the effect you''re trying to get. That would disguise what the actual patterns really are but also show people that the OOF was deliberate', '2006-02-09 18:20:24.000000', NULL, 1),
(2137836, 291196, 42984, '<td valign="top">Interesting subject and the compositon is attractive too. I have a feeling that mono has lost something in this. B&amp;W seems to have more impact too if you increase the contrast a little to give a little more emphasis to the textures and shades. Also it''s just a little unsharp but that would be the case if you didn''t sharpen it after reducing it to 640x</td>', 'Interesting subject and the compositon is attractive too. I have a feeling that mono has lost something in this. B&W seems to have more impact too if you increase the contrast a little to give a little more emphasis to the textures and shades. Also it''s just a little unsharp but that would be the case if you didn''t sharpen it after reducing it to 640x', '2006-02-09 18:23:29.000000', NULL, 1),
(2137842, 290671, 42984, '<td valign="top">This si a great still-life study of the lamp but is not quite abstract. For abstract we''re expecting to see interesting shapes and colours but not be able to tell what they are.</td>', 'This si a great still-life study of the lamp but is not quite abstract. For abstract we''re expecting to see interesting shapes and colours but not be able to tell what they are.', '2006-02-09 18:24:42.000000', NULL, 1),
(2137848, 290853, 42984, '<td valign="top">Now those drops are pretty cool. Did the out of focus ones to the bottom-right worry you? They do me a little. I wonder if it would have held up if you''d cropped it harder, perhaps vertivally just above the letter "C" of the title?</td>', 'Now those drops are pretty cool. Did the out of focus ones to the bottom-right worry you? They do me a little. I wonder if it would have held up if you''d cropped it harder, perhaps vertivally just above the letter "C" of the title?', '2006-02-09 18:26:25.000000', NULL, 1),
(2137866, 289206, 42984, '<td valign="top">Good form and colour, cn''t tell what it is but it is captivating. The grain and colour in the bottom left show how much you''ve pushed it, perhaps just a little too much making it detectable?</td>', 'Good form and colour, cn''t tell what it is but it is captivating. The grain and colour in the bottom left show how much you''ve pushed it, perhaps just a little too much making it detectable?', '2006-02-09 18:29:27.000000', NULL, 1),
(2137870, 289904, 42984, '<td valign="top">Very good artisitc design</td>', 'Very good artisitc design', '2006-02-09 18:30:01.000000', NULL, 1),
(2137879, 290693, 42984, '<td valign="top">Interesting image. There are a lot of elements here and I''m not quite sure which is supposed to have my attention. The result is that nothing does. The OOF object to the right is really distracting so maybe it would have better been left out do you think?</td>', 'Interesting image. There are a lot of elements here and I''m not quite sure which is supposed to have my attention. The result is that nothing does. The OOF object to the right is really distracting so maybe it would have better been left out do you think?', '2006-02-09 18:31:53.000000', NULL, 1),
(2137886, 290798, 42984, '<td valign="top">Excellent use of oight and coulour. I love the variance of the colours on the fan vs the backdrop, you''ve almost got a full spectrum going there. The motion blur on the fan spoils it a little.</td>', 'Excellent use of oight and coulour. I love the variance of the colours on the fan vs the backdrop, you''ve almost got a full spectrum going there. The motion blur on the fan spoils it a little.', '2006-02-09 18:33:42.000000', NULL, 1),
(2137891, 291827, 51675, '<td valign="top">I don''t gety it! OH, yes I do! Brilliant! Genious!  Your the next Abstract King!</td>', 'I don''t gety it! OH, yes I do! Brilliant! Genious!  Your the next Abstract King!', '2006-02-09 18:35:25.000000', NULL, 1),
(2137892, 291695, 42984, '<td valign="top">Reall good abstract. It''s clear, clean, interesting and has a great glow abou it.</td>', 'Reall good abstract. It''s clear, clean, interesting and has a great glow abou it.', '2006-02-09 18:35:32.000000', NULL, 1),
(2137896, 289018, 42984, '<td valign="top">I''d really have liked this if I could have found one small area in focus</td>', 'I''d really have liked this if I could have found one small area in focus', '2006-02-09 18:36:10.000000', NULL, 1),
(2137906, 291537, 42984, '<td valign="top">What a great piece of art</td>', 'What a great piece of art', '2006-02-09 18:39:17.000000', NULL, 1),
(2137907, 291553, 42984, '<td valign="top">Fascinating colours whaich have been macroed in a way that thye become abstract.</td>', 'Fascinating colours whaich have been macroed in a way that thye become abstract.', '2006-02-09 18:39:57.000000', NULL, 1),
(2137910, 291246, 42984, '<td valign="top">Really good image. The colours are great and the abstractness of the composition makes this something you might see in corporate art on their walls</td>', 'Really good image. The colours are great and the abstractness of the composition makes this something you might see in corporate art on their walls', '2006-02-09 18:41:03.000000', NULL, 1),
(2137915, 290516, 42984, '<td valign="top">Well seen and well shot.</td>', 'Well seen and well shot.', '2006-02-09 18:41:29.000000', NULL, 1),
(2137920, 290447, 42984, '<td valign="top">I love the colour, the symmetry and the shapes. I like less that there isn''t a focus point that''s easy to find. It may be there but is just too hard to find</td>', 'I love the colour, the symmetry and the shapes. I like less that there isn''t a focus point that''s easy to find. It may be there but is just too hard to find', '2006-02-09 18:42:39.000000', NULL, 1),
(2137927, 289694, 42984, '<td valign="top">Cool. Sharpness is terrific, colour is great and the light is just right but something doesn''t go wow. I wonder if its the centred composition?</td>', 'Cool. Sharpness is terrific, colour is great and the light is just right but something doesn''t go wow. I wonder if its the centred composition?', '2006-02-09 18:44:10.000000', NULL, 1),
(2138012, 291839, 43565, '<td valign="top">Love the title!</td>', 'Love the title!', '2006-02-09 19:06:25.000000', NULL, 1),
(2138025, 291528, 42984, '<td valign="top">The symmetry and colours make this a terrific abstract. What bugs me though i that it looks as if your verticals are tilted right. That looks sloppy and as if you don''t care too much.</td>', 'The symmetry and colours make this a terrific abstract. What bugs me though i that it looks as if your verticals are tilted right. That looks sloppy and as if you don''t care too much.', '2006-02-09 19:12:17.000000', NULL, 1),
(2138030, 291352, 42984, '<td valign="top">LOve it, really good use of zoom blur. How many comments have you had that it''s OOF ... LOL</td>', 'LOve it, really good use of zoom blur. How many comments have you had that it''s OOF ... LOL', '2006-02-09 19:13:11.000000', NULL, 1),
(2138039, 291665, 42984, '<td valign="top">That''s a prettu cool image. Simplicity works, a lot of people are scared of it, not you. I struggled to find a focus point even though I know that''s not what it is about, but it did dis-comfort me just a little</td>', 'That''s a prettu cool image. Simplicity works, a lot of people are scared of it, not you. I struggled to find a focus point even though I know that''s not what it is about, but it did dis-comfort me just a little', '2006-02-09 19:15:12.000000', NULL, 1),
(2138041, 291365, 42984, '<td valign="top">Very cool, nice piece of art. Good colours and good form.</td>', 'Very cool, nice piece of art. Good colours and good form.', '2006-02-09 19:15:52.000000', NULL, 1),
(2138044, 289498, 43565, '<td valign="top">"If it is recognizable as an object - it is not an abstract."</td>', '"If it is recognizable as an object - it is not an abstract."', '2006-02-09 19:16:37.000000', NULL, 1),
(2138046, 291761, 42984, '<td valign="top">Well composed and lit. I can imagin that this object, whatever it is, could be really boring. That you''ve turned it into something interesting is testament to your skill.</td>', 'Well composed and lit. I can imagin that this object, whatever it is, could be really boring. That you''ve turned it into something interesting is testament to your skill.', '2006-02-09 19:16:52.000000', NULL, 1),
(2138050, 291698, 42984, '<td valign="top">Well set up. The depthe of the objects makes it really interesting and draws you into looking at it further. I''m not sure that I am comfortable with the colour treatment or the blown highlights.</td>', 'Well set up. The depthe of the objects makes it really interesting and draws you into looking at it further. I''m not sure that I am comfortable with the colour treatment or the blown highlights.', '2006-02-09 19:18:25.000000', NULL, 1),
(2138052, 291367, 42984, '<td valign="top">I would hang that on our office wall. Well done.</td>', 'I would hang that on our office wall. Well done.', '2006-02-09 19:19:03.000000', NULL, 1),
(2138062, 291364, 42984, '<td valign="top">Even though I can tell what it is, I rather like the symmetry and compositon. The colours work too. What doesn''t work quite so well is the depth of field. Since you were some distance (6ft?) from the lower cornice and perhaps 9ft from the roof edge, you should have been able to get all the planes in focus. You''d have to use the smallest aperture that you have available, at least F8.0. With the amount of light available, you''d still have had a shutter speed that wouldn''t blur.</td>', 'Even though I can tell what it is, I rather like the symmetry and compositon. The colours work too. What doesn''t work quite so well is the depth of field. Since you were some distance (6ft?) from the lower cornice and perhaps 9ft from the roof edge, you should have been able to get all the planes in focus. You''d have to use the smallest aperture that you have available, at least F8.0. With the amount of light available, you''d still have had a shutter speed that wouldn''t blur.', '2006-02-09 19:22:23.000000', NULL, 1),
(2138069, 291688, 32133, '<td valign="top">Love this shot.  May look more abstract with the bottom windows cropped out.  Even though I''ve saw this building many times when I lived in Orlando, I wouldn''t have recognized it without the title.</td>', 'Love this shot.  May look more abstract with the bottom windows cropped out.  Even though I''ve saw this building many times when I lived in Orlando, I wouldn''t have recognized it without the title.', '2006-02-09 19:24:18.000000', NULL, 1),
(2138070, 290513, 42984, '<td valign="top">The angles and curves along with the fat pipe vs small pipe makes for an intersting abstract. I think you''ve maybe pushed the contrast and colour a little too hard because of the way the highlights have blown out. If you puch the contrast hard you can sometimes then lessen Brightness and avoid this.</td>', 'The angles and curves along with the fat pipe vs small pipe makes for an intersting abstract. I think you''ve maybe pushed the contrast and colour a little too hard because of the way the highlights have blown out. If you puch the contrast hard you can sometimes then lessen Brightness and avoid this.', '2006-02-09 19:24:21.000000', NULL, 1),
(2138076, 291739, 42984, '<td valign="top">Good wrok keepinh the rings nice and sharp top to bottom. The contrast with their background blurriness suggests they''re in orbit. It''s a good fun image.</td>', 'Good wrok keepinh the rings nice and sharp top to bottom. The contrast with their background blurriness suggests they''re in orbit. It''s a good fun image.', '2006-02-09 19:25:40.000000', NULL, 1),
(2138078, 291182, 42984, '<td valign="top">Good combo of macro and motion blur. The colours are cool too.</td>', 'Good combo of macro and motion blur. The colours are cool too.', '2006-02-09 19:26:14.000000', NULL, 1),
(2138079, 288203, 43565, '<td valign="top">I like the shot, but the border is too wide for me.</td>', 'I like the shot, but the border is too wide for me.', '2006-02-09 19:26:17.000000', NULL, 1),
(2138091, 288135, 43565, '<td valign="top">I love the texture.</td>', 'I love the texture.', '2006-02-09 19:28:08.000000', NULL, 1),
(2138098, 291312, 42984, '<td valign="top">Great subject and colour! The metallic red thru grey thru blue is enticing. I don''t know where these were but I''m guessing in a public place so cleaning them was probably a real issue. However cleaned they must be. It just doesn''t work as it is. Apart from anything else, the dust particles reveal the scale and spoil the mystery.</td>', 'Great subject and colour! The metallic red thru grey thru blue is enticing. I don''t know where these were but I''m guessing in a public place so cleaning them was probably a real issue. However cleaned they must be. It just doesn''t work as it is. Apart from anything else, the dust particles reveal the scale and spoil the mystery.', '2006-02-09 19:28:32.000000', NULL, 1),
(2138101, 289701, 32133, '<td valign="top">Very cool...</td>', 'Very cool...', '2006-02-09 19:28:44.000000', NULL, 1),
(2138107, 291794, 32133, '<td valign="top">Very interesting!  Definately meets the challenge.</td>', 'Very interesting!  Definately meets the challenge.', '2006-02-09 19:29:28.000000', NULL, 1),
(2138108, 291500, 32133, '<td valign="top">Simply beautiful</td>', 'Simply beautiful', '2006-02-09 19:29:32.000000', NULL, 1),
(2138110, 290693, 32133, '<td valign="top">Great colors</td>', 'Great colors', '2006-02-09 19:29:37.000000', NULL, 1),
(2138111, 291811, 42984, '<td valign="top">Great stuff. Very creative and refreshingly simple. The neutral space forms the composition and it is the composition which makes this really work</td>', 'Great stuff. Very creative and refreshingly simple. The neutral space forms the composition and it is the composition which makes this really work', '2006-02-09 19:29:39.000000', NULL, 1),
(2138115, 291507, 32133, '<td valign="top">Nice crisp focus.  Good depth of field. I love the monochromatic feel.</td>', 'Nice crisp focus.  Good depth of field. I love the monochromatic feel.', '2006-02-09 19:29:46.000000', NULL, 1),
(2138116, 290508, 32133, '<td valign="top">Beautiful shot.  I love the red tones.</td>', 'Beautiful shot.  I love the red tones.', '2006-02-09 19:29:49.000000', NULL, 1),
(2138133, 291425, 42984, '<td valign="top">Now this is really quite a cool image. It''s got that mystery that has you sitting there trying to work out what it is. You''ve heard people say not to try borders as they polarise voters. I don''t usually mind but your red one stands out and I think that makes it a distraction. The black is ok because it in all probability enhances the image without being noticed all on its own</td>', 'Now this is really quite a cool image. It''s got that mystery that has you sitting there trying to work out what it is. You''ve heard people say not to try borders as they polarise voters. I don''t usually mind but your red one stands out and I think that makes it a distraction. The black is ok because it in all probability enhances the image without being noticed all on its own', '2006-02-09 19:32:19.000000', NULL, 1),
(2138141, 291780, 42984, '<td valign="top">Mmm nive. The flow and the ngles combined with the subdued blue/black/pink are really zappy. I find not being able to find a point that''s focussed a little frustrating</td>', 'Mmm nive. The flow and the ngles combined with the subdued blue/black/pink are really zappy. I find not being able to find a point that''s focussed a little frustrating', '2006-02-09 19:34:10.000000', NULL, 1),
(2138166, 290797, 42984, '<td valign="top">Superb, well spotted, composed and cropped</td>', 'Superb, well spotted, composed and cropped', '2006-02-09 19:39:45.000000', NULL, 1),
(2138173, 291444, 42984, '<td valign="top">I love the composition and the colours, this could have been a really good abstract but some part of it really needs to be in focus for it to work.</td>', 'I love the composition and the colours, this could have been a really good abstract but some part of it really needs to be in focus for it to work.', '2006-02-09 19:41:12.000000', NULL, 1),
(2138176, 291003, 42984, '<td valign="top">Neat use of form amd good use of DOF which I image wasn''t easy. Looking forward to finding out what it is.</td>', 'Neat use of form amd good use of DOF which I image wasn''t easy. Looking forward to finding out what it is.', '2006-02-09 19:42:30.000000', NULL, 1),
(2138196, 291056, 42984, '<td valign="top">This is a well-designed piece of artwork. It''s a pity the grain/noise is so pronounced as it really spoils the sharpness and clarity of what is basically so good.</td>', 'This is a well-designed piece of artwork. It''s a pity the grain/noise is so pronounced as it really spoils the sharpness and clarity of what is basically so good.', '2006-02-09 19:48:01.000000', NULL, 1),
(2138197, 291833, 42984, '<td valign="top">So simple and so powerfull. Another example od less is more.</td>', 'So simple and so powerfull. Another example od less is more.', '2006-02-09 19:48:34.000000', NULL, 1),
(2138203, 291570, 42984, '<td valign="top">My initial reaction was that this wasn''t very abstract but it is nevertheless a very intersting quality image. The bronze of the propellor matches the gold of the hull nd the bright pieces of the anti-fouling on the rudder and stern are like two puntuation points. It would make a fabulous framed print.</td>', 'My initial reaction was that this wasn''t very abstract but it is nevertheless a very intersting quality image. The bronze of the propellor matches the gold of the hull nd the bright pieces of the anti-fouling on the rudder and stern are like two puntuation points. It would make a fabulous framed print.', '2006-02-09 19:51:22.000000', NULL, 1),
(2138209, 291765, 42984, '<td valign="top">This is powerful but also strikes me as sort of messy. Ny eye is having trouble finding  place to rest and that works against a wow feeling</td>', 'This is powerful but also strikes me as sort of messy. Ny eye is having trouble finding  place to rest and that works against a wow feeling', '2006-02-09 19:52:42.000000', NULL, 1),
(2138223, 291210, 42984, '<td valign="top">Crazy and cool</td>', 'Crazy and cool', '2006-02-09 19:58:37.000000', NULL, 1),
(2138226, 291070, 42984, '<td valign="top">This is an awesome setup. The reflective qualities of the base is outstanding ... all to be spoiled because it is out of focus. Did you resharpen after you reduced it to 640x ... you must do that.</td>', 'This is an awesome setup. The reflective qualities of the base is outstanding ... all to be spoiled because it is out of focus. Did you resharpen after you reduced it to 640x ... you must do that.', '2006-02-09 20:00:14.000000', NULL, 1),
(2138230, 290146, 42984, '<td valign="top">I love the geometry of geodesic domes, nice capture.</td>', 'I love the geometry of geodesic domes, nice capture.', '2006-02-09 20:00:52.000000', NULL, 1),
